/**
 * Interface dictionaries (audit A17, blueprint §16).
 *
 * `en` is the source of truth for keys; `es` must carry the
 * same keys (TypeScript enforces it). t() falls back to the
 * English string for any key a locale hasn't translated, so
 * the UI can never render a raw key or a blank.
 *
 * Spanish copy rules (Ryan's quality rule): neutral
 * professional business Spanish; mechanics' vocabulary done
 * properly — herramienta (tool), inventario (inventory),
 * reclamo (an insurance claim), garantía (warranty),
 * préstamo (a lend/borrow). User-generated content is NEVER
 * in these dictionaries — only interface chrome.
 *
 * PHASE 1 surfaces (complete): shell/nav, auth, landing,
 * home, settings appearance + language, inventory list
 * chrome, claims list chrome. Everything else is phase 2
 * (logged in the build queue) and renders English until then.
 */

