  "shared.subtitle":
    "Search the lists your crew shares with you, browse a person's tools, and share your own list — all in one place.",
  "shared.tab.how": "How it works",
  "shared.tab.withMe": "Shared with me",
  "shared.tab.sharing": "I am sharing",
  "shared.tab.settings": "Sharing settings",
  "shared.fact.invitesWaiting": "Invites waiting",
  "shared.how.whatTitle": "What this is",
  "shared.how.whatBody":
    "Shared tools connects your tool list with the people you work with. When a coworker shares their list with you, you can search it and browse it here — and when you need a tool, you can ask to borrow it right from the item.",
  "shared.how.seeTitle": "What people see",
  "shared.how.seeBody":
    "A shared list shows only the basics: name, brand, model, category, and photos. Prices, notes, and serial numbers never leave the owner's vault.",
  "shared.how.shareTitle": "Sharing your list",
  "shared.how.shareBody":
    "You decide who sees your list. Invite people by account number or email, hide any items you don't want seen, and stop sharing whenever you like — it's all in the Sharing settings tab. The same place shares your list with your shop or insurance group, on the terms you set.",
  "shared.how.borrowTitle": "Borrowing",
  "shared.how.borrowBody":
    "Found a tool you need? Open it and hit Request to borrow. The owner approves it from their Borrowing page, and the tool checks out to you.",
  "shared.how.seeWithMe": "See what's shared with me",
  "shared.how.openSettings": "Open sharing settings",
  "shared.sharing.peopleTitle": "People you share with",
  "shared.sharing.empty": "You're not sharing your list with anyone yet.",
  "shared.sharing.emailNote": "invited by email",
  "shared.sharing.badgeSharing": "Sharing",
  "shared.sharing.badgeInvited": "Invited",
  "shared.sharing.manage": "Manage sharing",
  "shared.sharing.manageNote":
    "Invite people, hide items, or stop sharing — from the Sharing settings tab.",
