  "shared.tab.employees": "Employees",
  "shared.how.audiencesTitle": "Four audiences, one hub",
  "shared.how.audiencesBody":
    "Each tab above is one audience — your employer, your insurance company, your coworkers, and your employees — and shows who is in it and exactly what they can see. Nothing is shared with anyone until you choose it, and every audience's controls live together in the Sharing settings tab.",
  "shared.aud.on": "Sharing on",
  "shared.aud.off": "Sharing off",
