  "shared.emp.shopsTitle": "Your employer",
  "shared.emp.shopsEmpty":
    "You're not on any shop's crew right now. When a shop invites you to its crew and you accept, the shop shows up here.",
  "shared.emp.colShop": "Shop",
  "shared.emp.seesTitle": "What your employer sees",
  "shared.emp.seesOnCrew":
    "Your shop can open your list from its crew page and sees exactly these items — nothing more. That window exists only while you're an active crew member there; leaving the crew closes it, and turning this sharing off closes it right away.",
  "shared.emp.seesOnNoCrew":
    "This sharing is switched on, but you're not an active member of any shop's crew right now — so no shop can open your list. A shop gets its window only while you're on its crew.",
  "shared.emp.seesOff":
    "Sharing with your shop is off, so your employer sees none of your items — even while you're on their crew. Turn it on in the Sharing settings tab if you want them to see the items you pick.",
  "shared.emp.fromTitle": "Shared with you by your employer",
  "shared.emp.fromEmpty":
    "Your employer hasn't shared a list with you person-to-person. If they do, it shows up here and in the Coworkers tab.",
  "shared.emp.fromNote":
    "Person-to-person shares from your shop's account — the same lists you can search in the Coworkers tab.",
  "shared.ins.companyTitle": "Your insurance company",
  "shared.ins.companyPicked": "Your company, from the directory: {name}",
  "shared.ins.companyTyped":
    "You've written your company as “{name}”, but it isn't linked to a company in the directory yet. Link it in Settings → My insurance so an insurer can be matched to your sharing.",
  "shared.ins.companyNone":
    "You haven't named your insurance company yet. Add it in Settings → My insurance — picking a company from the directory is what connects it to your sharing here.",
  "shared.ins.agentLine": "Your agent: {name}",
  "shared.ins.openProfile": "Open My insurance",
  "shared.ins.seesTitle": "What your insurance company sees",
  "shared.ins.seesOnMatched":
    "A verified insurance user at {name} can see exactly these items — the fields you chose, and nothing else. Both locks have to be open: the company pick above, and this sharing switch.",
  "shared.ins.seesOnUnmatched":
    "This sharing is switched on, but no insurance company is matched to it yet — link your company from the directory above and a verified insurance user there can see exactly these items. Until then, nobody does.",
  "shared.ins.seesOff":
    "Sharing with the insurance group is off, so no insurance company sees any of your items. Turn it on in the Sharing settings tab if you want your insurer to see the items you pick.",
  "shared.ins.stateTitle": "Where insurance sharing stands today",
  "shared.ins.stateBody":
    "Honest current state: insurance companies are in a directory Toolbox Vault keeps, and insurance users are verified by Toolbox Vault — insurance accounts can't sign themselves up yet. Sharing here never files a claim and gives no insurer access to your Disaster Claims; it only shows a verified insurer at your company the items you picked, with the details you chose.",
  "shared.cow.title": "Coworkers",
  "shared.cow.intro":
    "Person-to-person sharing: the coworkers whose lists you can search and browse, and the coworkers who can see yours. This is the sharing the Borrowing page grows out of.",
  "shared.empl.title": "Your crew",
  "shared.empl.colEmployee": "Employee",
  "shared.empl.colSeesMine": "Sees my list",
  "shared.empl.seesYes": "Yes — shared person-to-person",
  "shared.empl.seesInvited": "Invited — waiting for them",
  "shared.empl.seesNo": "No",
  "shared.empl.empty":
    "Nobody is in your crew yet. Invite people from Settings → Crew and they'll show up here.",
  "shared.empl.gateNote":
    "Crew membership by itself shares nothing, in either direction. An employee sees your list only if you also share it with them person-to-person (the Coworkers controls), and you see an employee's list only when they share with the shop group — their choice, in their own sharing settings. What each employee shares with the shop is in Settings → Crew.",
  "shared.empl.openCrew": "Open Crew settings",
  "shared.empl.notShopTitle": "Employees are a shop feature",
  "shared.empl.notShopBody":
    "This tab is for shop accounts and their crews. Your account doesn't run a shop crew, so there's no employee list to show — the people you work with are in the Coworkers tab, and your own shop, if you're on a crew, is in the Employer tab.",
