  // -- onboarding wizard (owner design 2026-10-31, built
  //    2026-11-07): the guided setup pass over the real settings.
  "setup.title": "Account setup",
  "setup.subtitle":
    "One guided pass over everything your account can be. Every choice here also lives in Settings, and every one can be changed at any time.",
  "setup.banner.title": "Finish setting up your account",
  "setup.banner.body":
    "A short guided pass: the kind of work you do, the basics, your modules, and how you share. Skip anything — you can come back whenever you like.",
  "setup.banner.bodyBare":
    "A short guided pass over your account basics — language, look, notifications, and your public profile. Skip anything — you can come back whenever you like.",
  "setup.banner.cta": "Start setup",
  "setup.banner.resume": "Continue setup",
  "setup.banner.dismiss": "Dismiss",
  "setup.banner.newFeature": "A new feature is available",
  "setup.banner.newFeatureBody":
    "Something new landed in your vault. Open setup to see it, turn it on, and walk through its options.",
  "setup.banner.newFeatureCta": "See what's new",
  "setup.bare.title": "Welcome to your vault",
  "setup.bare.body":
    "This is your home page — bare on purpose, for now. Finish the quick setup and it fills with your tools, your work, and the things you check every day.",
  "setup.bare.public":
    "While you decide, the menu still takes you everywhere public: the dealer directory, the community boards, and the how-to videos.",
  "setup.progress.title": "Your setup progress",
  "setup.progress.of": "{done} of {total} done",
  "setup.progress.allDone": "All set — your account is fully set up.",
  "setup.step.done": "Done",
  "setup.step.skipped": "Skipped",
  "setup.step.todo": "To do",
  "setup.step.new": "New",
  "setup.example.label": "Example",
  "setup.back": "Back",
  "setup.skip": "Skip this step",
  "setup.continue": "Save & continue",
  "setup.finish": "Finish setup",
  "setup.accountType.title": "What kind of work do you do?",
  "setup.accountType.intro":
    "Pick everything that fits — a lot of people wear more than one hat. Your pick decides which pages, tools, and modules your vault shows you. This is the one step the rest of the pass builds on, so it stays on your list until it's picked.",
  "setup.accountType.example":
    "A mechanic who also sells tools picks Mechanic / Technician AND Tool Dealer — one account, both sets of pages, no second login.",
  "setup.accountType.needOne": "Pick at least one to continue. Your account type decides which modules you can pick — a mechanic's list doesn't include dealer modules — so setup needs this answer before the modules step can open.",
  "setup.locked.body": "The rest of setup builds on your account type: it decides which settings you walk through and which modules are yours to pick. Pick your type above and the remaining steps unlock.",
  "setup.basics.title": "The basics",
  "setup.basics.intro":
    "Where you are, how your money reads, your language, and your color — pre-filled with the usual defaults, ready to change.",
  "setup.basics.example":
    "Pick Canada and your prices read in Canadian dollars everywhere. Amounts are never converted behind your back; they simply display in your currency.",
  "setup.modules.title": "Your modules",
  "setup.modules.intro":
    "Modules are the big features of your vault. Everything your kind of work entitles is listed here, on the same switches as Settings → Modules. Turn off anything you don't want — you can flip it back at any time.",
  "setup.modules.example":
    "Never lend tools? Turn off Borrowing and its pages, menus, and home blocks leave your vault until you turn it back on.",
  "setup.newFeature.title": "New feature: {name}",
  "setup.newFeature.body":
    "This feature arrived after your account was set up. It's yours to use — flip its switch here (the same switch as Settings → Modules) and you're done, or skip and it stays quietly listed here.",
  "setup.settings.intro":
    "This is the {section} page from Settings, brought into the pass — anything you change here saves exactly the way it does there.",
  "setup.example.appearance":
    "Go light, go dark, pick your color — the whole site, buttons included, follows the look you choose.",
  "setup.example.customize":
    "Each page can be arranged your way: which blocks show, in what order, at what size.",
  "setup.example.custom-fields":
    "Track something the standard fields don't cover — a torque spec, a calibration date — as your own field on every tool.",
  "setup.example.wizard-defaults":
    "Add tools the same way every time? Pre-pick the sections and usual spots the Add wizard opens with, and skip the same clicks from then on.",
  "setup.example.dealer-list":
    "Your pick list for tool dealers — hide the brands you never buy, and add the local dealer who isn't in the directory yet.",
  "setup.example.dealer-profile":
    "Your public dealer profile: the company facts customers see when they find you in the directory.",
  "setup.example.crew":
    "Your crew: invite your technicians and keep the roster. What the shop sees of a member's tools is exactly what that member shares with the shop — nothing more.",
  "setup.example.my-shop":
    "The shop you belong to. The shop's own tools belong to the shop; your tools stay yours — you keep full rights to them and file your own claims on them.",
  "setup.example.my-shop-bare":
    "The shop you belong to. The shop's own things belong to the shop; your things stay yours — you keep full rights to them.",
  "setup.example.insurer-profile":
    "Your insurer profile — the company facts that ride your claim paperwork.",
  "setup.example.public-profile":
    "What other members see: a coarse area (never an address) and, only if you opt in, a phone number.",
  "setup.example.notifications":
    "Which events deserve an email and which just land in your inbox here — a claim deadline is worth an email; routine ledger noise usually isn't.",
  "setup.example.notifications-bare":
    "Which events deserve an email and which just land in your inbox here — an answer on a support ticket is worth an email; routine notices usually aren't.",
  "setup.example.sharing":
    "Share a tool's record with your shop or a coworker and they see exactly the fields you picked — a set's inventory can be shared with the crew while its prices stay private.",
  "setup.dismissSetup": "Dismiss setup",
  "setup.dismissConfirm":
    "Stop showing the setup banner? Nothing is locked and nothing is lost — you can reopen setup any time from Settings → Account setup.",
  "setup.settingsSection.done": "Your account is fully set up.",
  "setup.settingsSection.remaining": "{count} setup steps remain.",
  "setup.settingsSection.open": "Open the setup wizard",
  "setup.settingsSection.dismissed":
    "Setup was dismissed. Reopening brings the banner back until the pass is finished.",
  "setup.helpLink": "New here? Run the account setup wizard",
  "setup.legacy.body":
    "This account predates the setup wizard and still needs its account type and basics chosen. The classic one-time completion page handles that — nothing else about the account changes.",
  "setup.legacy.cta": "Finish the one-time setup",
