  "toolExpansion.how.whatTitle": "What this page does",
  "toolExpansion.how.whatBody":
    "Tool Expansion finds addons for the tools and sets you already own. It matches model numbers across the community's sets: when a set like yours carries extra pieces, those pieces show up here as matches for your item.",
  "toolExpansion.how.actTitle": "What you can do with a match",
  "toolExpansion.how.actBody":
    "Leave a match where it is, open it to look into the item or set it expands, or move it to your archived matches. Archiving is per item — the same piece can stay a match for one of your tools and sit archived for another.",
  "toolExpansion.how.reportTitle": "Reporting a match",
  "toolExpansion.how.reportBody":
    "If a match doesn't belong, report it. It disappears for you right away, and when enough owners report the same match it stops showing for everyone. Reporting is separate from archiving — a reported match never lands in your archive.",
