  "downloads.about.how1": "Elige una pestaña — Documentos, Archivos de impresión 3D o Fondos de pantalla.",
  "downloads.about.how2":
    "Encuentra el archivo que quieres. El contador de cada fila muestra cuántas veces se ha descargado.",
  "downloads.about.how3":
    "Haz clic en Descargar. El archivo se guarda directo en tu dispositivo — ese es todo el proceso.",
  "downloads.about.docsTitle": "Documentos",
  "downloads.about.docsBody":
    "Hojas de cálculo y formularios imprimibles para el taller: la hoja gratuita de inventario de herramientas, una calculadora de sueldo y horas extra, un registro de horas a tarifa plana, formularios de inspección, hojas de diagnóstico y una tabla de conversión de torque. Listos ahora, en la pestaña Documentos.",
  "downloads.about.printsTitle": "Archivos de impresión 3D",
  "downloads.about.printsBody":
    "Impresiones de herramientas y cajas compartidas por miembros registrados de la comunidad — gratis para que cualquiera las descargue, con calificaciones y comentarios de los miembros. Este estante tendrá su propia pestaña.",
  "downloads.about.wallpaperTitle": "Fondos de pantalla y arte",
  "downloads.about.wallpaperBody":
    "Fondos de pantalla en alta definición, con el tamaño justo para escritorio, tableta y teléfono — mecánicos, camiones de herramientas y arte de Toolbox Vault. Ya disponible, en la pestaña Fondos de pantalla.",
  "downloads.promise.never": "Tu correo nunca se vende.",
  "downloads.promise.ever": "Nunca.",
  "downloads.news.title": "Noticias del sitio por correo",
  "downloads.news.body":
    "Gratis, y completamente voluntario. Suscríbete y te escribiremos solo cuando haya novedades de verdad — descargas nuevas, funciones nuevas. Cada correo que enviamos incluye un enlace para cancelar la suscripción.",
