  "downloads.file.pre-purchase-form.name": "Formulario de inspección precompra de vehículos",
  "downloads.file.pre-purchase-form.desc":
    "¿Vas a comprar un vehículo usado? Revísalo con este formulario — calificaciones de condición por área, una lista de señales de alerta y un resumen de comprar o alejarse.",
  "downloads.file.diagnostic-worksheet.name": "Hoja de trabajo de diagnóstico",
  "downloads.file.diagnostic-worksheet.desc":
    "Una hoja estructurada para perseguir un problema: el problema en palabras del cliente, cuándo ocurre, códigos, pruebas, lecturas y la solución.",
