  "disasterClaims.how.whatBody":
    "Cuando las herramientas se roban, se queman, se inundan o se pierden en un evento de gran escala, el reclamo de seguro vive aquí. Inicie uno y obtiene su propio número DC-, su propia lista de tareas y sus propios plazos — todo en este mismo lugar.",
  "disasterClaims.how.sepTitle": "Separado de los reclamos de reparación",
  "disasterClaims.how.sepBody":
    "Reclamos por desastre es un módulo propio, 100% separado de los reclamos de garantía y reparación. Los reclamos de reparación viven en Reparaciones y mantenimiento — nunca aparecen aquí, y los reclamos por desastre nunca aparecen allí.",
  "disasterClaims.how.runTitle": "Cómo avanza un reclamo",
  "disasterClaims.how.runBody":
    "Presente el reclamo, agregue los artículos que cubre y luego trabaje la lista de tareas del reclamo: los documentos y las fotos que su aseguradora necesita, reunidos en la página del propio reclamo. Plazos como la prueba de pérdida se mantienen a la vista hasta cumplirse, y el reclamo avanza de presentado, a en revisión, a aprobado y pagado.",
  "disasterClaims.how.valueTitle": "Valorado a lo que pagó",
  "disasterClaims.how.valueBody":
    "Cada monto en un reclamo por desastre lleva el costo de compra del artículo — lo que realmente pagó por él. Nunca cifras de reemplazo ni inventadas.",
  "disasterClaims.how.seeOpen": "Ver reclamos abiertos",
  "disasterClaims.col.insurer": "Aseguradora",
  "disasterClaims.empty.title": "Aún no hay reclamos por desastre",
  "disasterClaims.empty.body":
    "Cuando algo se robe, se pierda o se dañe en un evento de magnitud de desastre, inicie el reclamo aquí: el proceso lo guía por los artículos, el incidente y la evidencia, y mantiene los plazos a la vista.",
  "disasterClaims.startFirst": "Inicie su primer reclamo por desastre",
  "disasterClaims.polOverdue": "Prueba de pérdida vencida",
  "disasterClaims.polDueSoon": "Prueba de pérdida por vencer",
  "disasterClaims.openEmpty.title": "Sin reclamos por desastre abiertos",
  "disasterClaims.openEmpty.body":
    "Todo lo que hay está terminado: los reclamos por desastre cerrados y archivados viven en Reclamos cerrados.",
  "disasterClaims.historyEmpty.title": "Aún no hay historial de reclamos por desastre",
  "disasterClaims.historyEmpty.body":
    "Los reclamos por desastre terminados, cerrados y archivados se reunirán aquí.",
