  "settings.section.setup": "Configuración de la cuenta",
  // -- onboarding wizard (owner design 2026-10-31, built
  //    2026-11-07): the guided setup pass over the real settings.
  "setup.title": "Configuración de la cuenta",
  "setup.subtitle":
    "Un recorrido guiado por todo lo que su cuenta puede ser. Cada opción aquí también está en Ajustes, y todas se pueden cambiar en cualquier momento.",
  "setup.banner.title": "Termine de configurar su cuenta",
  "setup.banner.body":
    "Un recorrido corto y guiado: el tipo de trabajo que hace, lo básico, sus módulos y cómo comparte. Salte lo que quiera — puede volver cuando guste.",
  "setup.banner.bodyBare":
    "Un recorrido corto y guiado por lo básico de su cuenta — idioma, apariencia, notificaciones y su perfil público. Salte lo que quiera — puede volver cuando guste.",
  "setup.banner.cta": "Empezar la configuración",
  "setup.banner.resume": "Continuar la configuración",
  "setup.banner.dismiss": "Descartar",
  "setup.banner.newFeature": "Hay una función nueva disponible",
  "setup.banner.newFeatureBody":
    "Algo nuevo llegó a su bóveda. Abra la configuración para verlo, activarlo y recorrer sus opciones.",
  "setup.banner.newFeatureCta": "Ver la novedad",
  "setup.bare.title": "Bienvenido a su bóveda",
  "setup.bare.body":
    "Esta es su página de inicio — vacía a propósito, por ahora. Termine la configuración rápida y se llenará con sus herramientas, su trabajo y lo que revisa cada día.",
  "setup.bare.public":
    "Mientras decide, el menú sigue llevándolo a todo lo público: el directorio de distribuidores, los foros de la comunidad y los videos de ayuda.",
  "setup.progress.title": "Su progreso de configuración",
  "setup.progress.of": "{done} de {total} completados",
  "setup.progress.allDone": "Todo listo — su cuenta está completamente configurada.",
  "setup.step.done": "Hecho",
  "setup.step.skipped": "Saltado",
  "setup.step.todo": "Pendiente",
  "setup.step.new": "Nuevo",
  "setup.example.label": "Ejemplo",
  "setup.back": "Atrás",
  "setup.skip": "Saltar este paso",
  "setup.continue": "Guardar y continuar",
  "setup.finish": "Terminar la configuración",
  "setup.accountType.title": "¿Qué tipo de trabajo hace?",
  "setup.accountType.intro":
    "Marque todo lo que le aplique — mucha gente lleva más de un sombrero. Su elección decide qué páginas, herramientas y módulos le muestra su bóveda. Es el único paso sobre el que se construye el resto del recorrido, así que permanece en su lista hasta que lo elija.",
  "setup.accountType.example":
    "Un mecánico que también vende herramientas elige Mecánico / Técnico Y Distribuidor de herramientas — una sola cuenta, ambos conjuntos de páginas, sin un segundo inicio de sesión.",
  "setup.accountType.needOne": "Marque al menos una opción para continuar. Su tipo de cuenta decide qué módulos puede elegir — la lista de un mecánico no incluye los módulos de distribuidor — así que la configuración necesita esta respuesta antes de que se abra el paso de módulos.",
  "setup.locked.body": "El resto de la configuración se basa en su tipo de cuenta: decide qué ajustes recorre y qué módulos puede elegir. Elija su tipo arriba y los pasos restantes se desbloquearán.",
  "setup.basics.title": "Lo básico",
  "setup.basics.intro":
    "Dónde está, cómo se leen sus montos, su idioma y su color — ya llenado con los valores habituales, listo para cambiar.",
  "setup.basics.example":
    "Elija Canadá y sus precios se leerán en dólares canadienses en todas partes. Los montos nunca se convierten a sus espaldas; simplemente se muestran en su moneda.",
  "setup.modules.title": "Sus módulos",
  "setup.modules.intro":
    "Los módulos son las funciones grandes de su bóveda. Todo lo que su tipo de trabajo le otorga está aquí, con los mismos interruptores que Ajustes → Módulos. Apague lo que no quiera — puede volver a encenderlo cuando sea.",
  "setup.modules.example":
    "¿Nunca presta herramientas? Apague Préstamos y sus páginas, menús y bloques de inicio saldrán de su bóveda hasta que lo vuelva a encender.",
  "setup.newFeature.title": "Función nueva: {name}",
  "setup.newFeature.body":
    "Esta función llegó después de que su cuenta ya estaba configurada. Es suya: encienda su interruptor aquí (el mismo de Ajustes → Módulos) y listo, o sáltela y quedará listada aquí sin molestar.",
  "setup.settings.intro":
    "Esta es la página de {section} de Ajustes, traída al recorrido — todo lo que cambie aquí se guarda exactamente igual que allá.",
  "setup.example.appearance":
    "Claro, oscuro, el color que elija — todo el sitio, botones incluidos, sigue el aspecto que escoja.",
  "setup.example.customize":
    "Cada página se puede ordenar a su manera: qué bloques se muestran, en qué orden y de qué tamaño.",
  "setup.example.custom-fields":
    "Registre algo que los campos estándar no cubren — una especificación de torque, una fecha de calibración — como su propio campo en cada herramienta.",
  "setup.example.wizard-defaults":
    "¿Agrega herramientas siempre de la misma manera? Preelija las secciones y los lugares habituales con los que abre el asistente de alta, y sáltese los mismos clics desde entonces.",
  "setup.example.dealer-list":
    "Su lista de distribuidores de herramientas — oculte las marcas que nunca compra y agregue al distribuidor local que aún no está en el directorio.",
  "setup.example.dealer-profile":
    "Su perfil público de distribuidor: los datos de la empresa que los clientes ven cuando lo encuentran en el directorio.",
  "setup.example.crew":
    "Su equipo: invite a sus técnicos y mantenga la lista. Lo que el taller ve de las herramientas de un miembro es exactamente lo que ese miembro comparte con el taller — nada más.",
  "setup.example.my-shop":
    "El taller al que pertenece. Las herramientas propias del taller son del taller; las suyas siguen siendo suyas — conserva todos sus derechos sobre ellas y presenta sus propios reclamos.",
  "setup.example.my-shop-bare":
    "El taller al que pertenece. Las cosas propias del taller son del taller; las suyas siguen siendo suyas — conserva todos sus derechos sobre ellas.",
  "setup.example.insurer-profile":
    "Su perfil de aseguradora — los datos de la empresa que acompañan su documentación de reclamos.",
  "setup.example.public-profile":
    "Lo que otros miembros ven: una zona general (nunca una dirección) y, solo si usted lo acepta, un número de teléfono.",
  "setup.example.notifications":
    "Qué eventos merecen un correo y cuáles solo llegan a su bandeja aquí — un vencimiento de reclamo merece correo; el ruido rutinario del libro, por lo general, no.",
  "setup.example.notifications-bare":
    "Qué eventos merecen un correo y cuáles solo llegan a su bandeja aquí — una respuesta a un ticket de soporte merece correo; los avisos rutinarios, por lo general, no.",
  "setup.example.sharing":
    "Comparta el registro de una herramienta con su taller o un colega y verán exactamente los campos que usted eligió — el inventario de un juego se puede compartir con el equipo mientras sus precios quedan privados.",
  "setup.dismissSetup": "Descartar la configuración",
  "setup.dismissConfirm":
    "¿Dejar de mostrar el aviso de configuración? Nada se bloquea ni se pierde — puede reabrir la configuración cuando quiera desde Ajustes → Configuración de la cuenta.",
  "setup.settingsSection.done": "Su cuenta está completamente configurada.",
  "setup.settingsSection.remaining": "Quedan {count} pasos de configuración.",
  "setup.settingsSection.open": "Abrir el asistente de configuración",
  "setup.settingsSection.dismissed":
    "La configuración fue descartada. Al reabrirla, el aviso vuelve hasta que el recorrido esté terminado.",
  "setup.helpLink": "¿Nuevo aquí? Ejecute el asistente de configuración de la cuenta",
  "setup.legacy.body":
    "Esta cuenta es anterior al asistente de configuración y aún necesita elegir su tipo de cuenta y lo básico. La página clásica de finalización única se encarga de eso — nada más de la cuenta cambia.",
  "setup.legacy.cta": "Terminar la configuración única",
