  "settings.modules.title": "Módulos",
  "settings.modules.intro":
    "Elige qué partes de Toolbox Vault aparecen en tu cuenta. Desactivar un módulo lo oculta en todas partes — menús, página de inicio, búsqueda y notificaciones — pero nunca borra nada. Vuelve a activarlo cuando quieras y regresa tal como estaba. Los cambios se guardan al hacerlos: no hay botón de guardar.",
