  // -- Tool Expansion page + surfaces --------------------------
  "toolExpansion.title": "Expansión de herramientas",
  "toolExpansion.subtitle":
    "Accesorios que otros propietarios tienen para las mismas herramientas y juegos que usted — comparados por número de modelo. Pase los que no quiera a sus coincidencias archivadas e informe de una coincidencia que no corresponda.",
  "toolExpansion.loading": "Cargando…",
  "toolExpansion.loadFailed": "No se pudieron cargar sus expansiones.",
  "toolExpansion.emptyTitle": "Aún no hay expansiones conocidas para sus herramientas",
  "toolExpansion.emptyBody":
    "Cuando otros propietarios registren accesorios para un juego o herramienta que usted tenga, aparecerán aquí.",
  "toolExpansion.expandsYour": "Expande su",
  "toolExpansion.scopedTo": "Mostrando expansiones para {name}",
  "toolExpansion.scopedGeneric": "Mostrando expansiones para un artículo",
  "toolExpansion.showAll": "Mostrar todo",
  "toolExpansion.tabsLabel": "Secciones de Expansión de herramientas",
  "toolExpansion.tab.how": "Cómo funciona",
