  "toolExpansion.fact.archived": "Archivadas",
  "toolExpansion.how.whatTitle": "Qué hace esta página",
  "toolExpansion.how.whatBody":
    "Expansión de herramientas encuentra accesorios para las herramientas y juegos que ya tiene. Compara números de modelo con los juegos de la comunidad: cuando un juego como el suyo lleva piezas extra, esas piezas aparecen aquí como coincidencias para su artículo.",
  "toolExpansion.how.actTitle": "Qué puede hacer con una coincidencia",
  "toolExpansion.how.actBody":
    "Deje la coincidencia donde está, ábrala para ver el artículo o juego que expande, o pásela a sus coincidencias archivadas. Archivar es por artículo: la misma pieza puede seguir siendo coincidencia para una de sus herramientas y estar archivada para otra.",
  "toolExpansion.how.reportTitle": "Informar de una coincidencia",
  "toolExpansion.how.reportBody":
    "Si una coincidencia no corresponde, infórmela. Desaparece para usted de inmediato, y cuando suficientes propietarios informan de la misma coincidencia, deja de mostrarse para todos. Informar es distinto de archivar: una coincidencia informada nunca llega a su archivo.",
  "toolExpansion.how.seeMatches": "Ver sus coincidencias",
  "toolExpansion.moveToArchived": "Pasar a archivadas",
  "toolExpansion.archivedToast": "Pasada a sus coincidencias archivadas.",
  "toolExpansion.bringBack": "Recuperar",
