  "toolExpansion.archivedBody":
    "Coincidencias que apartó. Recupere una y volverá a sus coincidencias si todavía encaja con uno de sus artículos.",
  "toolExpansion.archivedEmptyTitle": "Aún no hay nada archivado",
  "toolExpansion.archivedEmptyBody":
    "Las coincidencias que aparte esperan aquí, para que pueda encontrarlas de nuevo.",
  "toolExpansion.archivedLoadFailed": "No se pudieron cargar sus coincidencias archivadas.",
  "toolExpansion.col.expands": "Expande",
